<script>
const lineas=document.getElementById('lineas'),promo=document.getElementById('promocion'),form=document.querySelector('[data-borrador]');
function renumerar(){lineas.querySelectorAll('.linea').forEach((l,i)=>l.querySelectorAll('[data-campo]').forEach(c=>c.name=`detalles[${i}][${c.dataset.campo}]`));}
function agregar(datos={}){lineas.append(document.getElementById('linea').content.cloneNode(true));const l=lineas.lastElementChild;l.querySelectorAll('[data-campo]').forEach(c=>{if(datos[c.dataset.campo]!==undefined)c.value=datos[c.dataset.campo];});renumerar();total();}
function total(){let t=0,base=0;const p=promo.selectedOptions[0];lineas.querySelectorAll('.linea').forEach(l=>{const s=l.querySelector('select');const importe=Math.round(Number(s.selectedOptions[0]?.dataset.precio||0)*100)*Number(l.querySelector('[data-campo=cantidad]').value||0);t+=importe;if(!p.dataset.producto || s.value===p.dataset.producto)base+=importe;});let d=0;if(p.value && !p.disabled){d=p.dataset.tipo==='Porcentaje' ? Math.round(base*Number(p.dataset.valor)/100) : Math.round(Number(p.dataset.valor)*100);if(p.dataset.tope!=='')d=Math.min(d,Math.round(Number(p.dataset.tope)*100));d=Math.max(0,Math.min(base,d));}document.getElementById('subtotal').textContent=(t/100).toFixed(2);document.getElementById('descuento').textContent=(d/100).toFixed(2);document.getElementById('total').textContent=((t-d)/100).toFixed(2);}
const anteriores=@json(old('detalles',$pedido->exists ? $pedido->detalles->toArray() : []));let inicio=anteriores;try{const saved=JSON.parse(localStorage.getItem(form.dataset.borrador)||'{}');if(!@json($errors->any()) && saved.lineas){inicio=saved.lineas;promo.value=saved.promocion_id||'';}}catch(e){}(inicio.length?inicio:[{}]).forEach(agregar);
document.getElementById('agregar').onclick=()=>{if(lineas.children.length<100){agregar();lineas.dispatchEvent(new Event('input',{bubbles:true}));}};
form.addEventListener('input',total);promo.addEventListener('change',total);lineas.addEventListener('click',e=>{if(e.target.matches('[data-quitar]')){e.target.closest('.linea').remove();renumerar();total();lineas.dispatchEvent(new Event('input',{bubbles:true}));}});
</script>
@endsection
